// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property() public {
        address ownerBefore = c.smartfix_owner();
        // Call sudicideAnyone with the owner
        vm.prank(ownerBefore);
        c.sudicideAnyone();
        address ownerAfter = c.smartfix_owner();
        assertTrue(ownerBefore == ownerAfter, "smartfix_owner should remain unchanged");
    }
}

