pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(c));
        address originalOwner = c.smartfix_owner();
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("sudicideAnyone()"));
        assertTrue(success || c.smartfix_owner() == originalOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // Restrict to caller != owner (contract owner is address(this) after setup)
        vm.assume(caller != address(this));
        // Attempt to call sudicideAnyone as a non-owner
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("sudicideAnyone()"));
        // The reference should revert, buggy version should succeed
        assertTrue(!success);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(this));
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        try c.sudicideAnyone() {
            // If call succeeded, caller must be the owner
            assertTrue(caller == c.smartfix_owner());
        } catch {
            // If call reverted, caller must not be the owner
            assertTrue(caller != c.smartfix_owner());
        }
    }
}
